# ── Special case: the greeting emoji in the hero title ───────────────────────
# "Good evening 👋" → just remove the wave, title is already nice
content = content.replace("${timeMsg} 👋<br>", "${timeMsg}<br>")

# ── Replace each emoji ───────────────────────────────────────────────────────
for emoji, svg in SVG.items():
    if emoji == '👋':
        continue  # handled above
    content = content.replace(emoji, svg)

# ── Special: the empty-state icon 📋 is inside a template as <div class="empty-icon"> ──
# Already replaced above with the larger version. But the empty-icon div uses font-size CSS
# so we need to handle size differently - keep the SVG at its set size

open('static/app.js', 'w', encoding='utf-8').write(content)
print('Done. Replaced all emojis with SVG icons.')

# Verify no emojis left
import re
remaining = re.findall(r'[\U0001F300-\U0001F9FF\U00002600-\U000027FF\U0000FE0F]+', content)
remaining_unique = set(remaining)
if remaining_unique:
    print('Still has emojis:', remaining_unique)
else:
    print('All emojis replaced!')
